{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"url": "/ds_salaries.csv"},
"title": "工资随时间发展折线",
  "width": 800,
  "height": 500,
  "transform": [
    {
      "filter": "datum.job_title !== null && datum.work_year !== null"
    },
    {
      "window": [
        {"op": "count", "as": "total_count"}
      ],
      "groupby": ["job_title"]
    },
    {
      "filter": "datum.total_count > 10"  
    },
    {
      "joinaggregate": [
        {"op": "mean", "field": "salary_in_usd", "as": "global_avg"}
      ],
      "groupby": ["job_title"]
    },
    {
      "window": [
        {"op": "dense_rank", "as": "rank"}
      ],
      "sort": [{"field": "global_avg", "order": "descending"}]
    },
    {
      "filter": "datum.rank <= 5"  
    },
    {
      "aggregate": [
        {
          "op": "mean",
          "field": "salary_in_usd",
          "as": "avg_salary_usd"
        }
      ],
      "groupby": ["work_year", "job_title"]
    }
  ],
  "mark": {
    "type": "line",
    "point": true,
    "interpolate": "monotone"
  },
  "encoding": {
    "x": {
      "field": "work_year",
      "type": "temporal",
      "title": "年份",
      "axis": {"format": "%Y"}
    },
    "y": {
      "field": "avg_salary_usd",
      "type": "quantitative",
      "title": "平均收入",
      "axis": {"format": "$,.0f"}
    },
    "color": {
      "field": "job_title",
      "type": "nominal",
      "title": "职位名称",
      "scale": {"scheme": "category10"}
    },
    "tooltip": [
      {"field": "work_year", "type": "temporal", "title": "年"},
      {"field": "job_title", "type": "nominal", "title": "位置"},
      {"field": "avg_salary_usd", "type": "quantitative", "title": "平均收入", "format": "$,.0f"},
      {"field": "global_avg", "type": "quantitative", "title": "全球平均", "format": "$,.0f"}
    ]
  },
  "config": {
    "legend": {
      "orient": "bottom",
      "columns": 2,
      "titleLimit": 200
    }
  }
}
